  Output.log(`成功设置关联目标表，字段ID: ${fieldId}`);
}

```

### getLinkedSheetId

获取当前关联的目标数据表ID。

```typescript
getLinkedSheetId: () => string

```

**返回值**

*   `string` - 目标数据表ID


**示例**

```typescript
// 获取关联的目标表ID
