TIMESTAMP=$(date +%Y%m%d_%H%M%S)
FILENAME="${TOPIC}_game_${GAME_MODE}_${TIMESTAMP}.html"
OUTPUT_PATH="$OUTPUT_DIR/$FILENAME"

print_info "正在生成文件: $FILENAME"

